INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(39911, 'Jeremiah 42:11', 'Jeremiah', 42, 11, 'مالِک خُدائ فرمائى چې، د بابل بادشاه نه نور مۀ يرېږئ. ځکه چې زۀ تاسو سره يم او د هغۀ نه به مو بچ کړم او د هغۀ د لاس نه به خلاصون درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah42_verse_11.mp3', '', 1761754199, 1761754199),
(39912, 'Jeremiah 42:12', 'Jeremiah', 42, 12, 'زۀ به په تاسو دا رحم وکړم چې هغه به درباندې مهربانه کړم، نو بيا به هغه تاسو ته په خپل مُلک کښې د پاتې کېدو اجازت درکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah42_verse_12.mp3', '', 1761754199, 1761754199),
(39913, 'Jeremiah 42:13', 'Jeremiah', 42, 13, 'خو کۀ چرې تاسو د مالِک خُدائ ستاسو خُدائ پاک د دې پېغام نه اِنکار وکړئ، او کۀ چرې تاسو ووايئ چې، نه، مونږ به دلته نۀ پاتې کيږُو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah42_verse_13.mp3', '', 1761754199, 1761754199),
(39914, 'Jeremiah 42:14', 'Jeremiah', 42, 14, 'خو د دې په ځائ به مِصر ته لاړ شُو، چرته چې به مونږ د جنګونو، د جنګ د بيګل آوازونو او قحط نه آزاد شُو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah42_verse_14.mp3', '', 1761754199, 1761754199),
(39915, 'Jeremiah 42:15', 'Jeremiah', 42, 15, 'نو بيا تاسو د مالِک خُدائ پېغام د يهوداه پاتې خلقو ته واوروئ. مالِک خُدائ ربُ الافواج داسې فرمائى چې، کۀ چرې تاسو دا ضرور غوره کړئ چې مِصر ته لاړ شئ او هلته پاتې شئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah42_verse_15.mp3', '', 1761754199, 1761754199),
(39916, 'Jeremiah 42:16', 'Jeremiah', 42, 16, 'د کوم جنګ او قحط نه چې تاسو يرېږئ نو هم هغه به تاسو راګېر کړى، او تاسو به هلته مړۀ شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah42_verse_16.mp3', '', 1761754199, 1761754199),
(39917, 'Jeremiah 42:17', 'Jeremiah', 42, 17, 'نو په حقيقت کښې چې څوک هم په تلو کلک ولاړ وى او هلته د اوسېدو اراده لرى نو هغه به په جنګ، قحط او په وبا مړ شى. په تاسو کښې به يو کس هم د هغه افت نه ونۀ تښتى کوم چې زۀ په تاسو باندې هلته راولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah42_verse_17.mp3', '', 1761754199, 1761754199),
(39918, 'Jeremiah 42:18', 'Jeremiah', 42, 18, 'مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى، لکه څنګه چې زما قهر او غضب د يروشلم په خلقو نازل شوے وو، نو کۀ تاسو مِصر ته لاړئ نو زما غضب به په تاسو هم نازل شى. نو ستاسو نوم به د تل دپاره د لعنت، يرې او مسخرې په توګه اخستلے کيږى او خپل مُلک به دوباره ونۀ وينئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah42_verse_18.mp3', '', 1761754199, 1761754199),
(39919, 'Jeremiah 42:19', 'Jeremiah', 42, 19, 'اے د يهوداه ژوندى پاتې شوى خلقو، مالِک خُدائ تاسو ته فرمائيلى دى چې مِصر ته مۀ ځئ. زۀ چې دا خبردارے نن تاسو ته درکوم دا مۀ هېروئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah42_verse_19.mp3', '', 1761754199, 1761754199),
(39920, 'Jeremiah 42:20', 'Jeremiah', 42, 20, 'ځکه تاسو چې کله زۀ مالِک خُدائ ته د خواست کولو دپاره ولېږلم نو تاسو غټه غلطى وکړه، ځکه چې تاسو ووئيل، د څۀ چې مالِک خُدائ مونږ ته حکم کړے دے هغه مونږ ته ووايه، مونږ به په هغې باندې پوره عمل کوُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah42_verse_20.mp3', '', 1761754199, 1761754199),
(39921, 'Jeremiah 42:21', 'Jeremiah', 42, 21, 'خو ما تاسو ته نن د هغۀ حکم واورولو، خو تاسو تر اوسه پورې د مالِک خُدائ د هغه پېغام پيروى نۀ کوئ د کوم دپاره چې تاسو زۀ استولے وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah42_verse_21.mp3', '', 1761754199, 1761754199),
(39922, 'Jeremiah 42:22', 'Jeremiah', 42, 22, 'نو اوس په دې خبره باندې يقين ساتئ چې، تاسو چې کوم ځائ ته تلل او اوسېدل غواړئ نو تاسو به هلته په جنګ، قحط او وبا مړۀ شئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah42_verse_22.mp3', '', 1761754199, 1761754199),
(39923, 'Proverbs 23:1', 'Proverbs', 23, 1, 'کله چې ته د اختیار د خاوند سره ډوډۍ خوړلو ته کښېنې نو ښه فکر وکړه چې ستا په مخکې څه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_1.mp3', '', 1761754199, 1761754199),
(39924, 'Proverbs 23:2', 'Proverbs', 23, 2, 'که ته ډېر خېټور انسان هم یې نو په خپله مرۍ دې چاړه کېږده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_2.mp3', '', 1761754199, 1761754199),
(39925, 'Proverbs 23:3', 'Proverbs', 23, 3, 'او د خوندورو خوړو نه یې د یوې مړۍ تمه هم مه لره ځکه چې دا خوراک ستا د چل او تېرایستلو دپاره دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_3.mp3', '', 1761754199, 1761754199),
(39926, 'Proverbs 23:4', 'Proverbs', 23, 4, 'د شتمنۍ د لاسته راوړلو دپاره ځان مه ستومانه کوه هوښیار اوسه او د داسې کار نه ځان وساته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_4.mp3', '', 1761754199, 1761754199),
(39927, 'Proverbs 23:5', 'Proverbs', 23, 5, 'ځکه ټوله شتمني به دې ناڅاپه د عقاب په شان وزرې پرانیزي او د سترګو په رپ کې به اسمان ته والوزي او ختمه به شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_5.mp3', '', 1761754199, 1761754199),
(39928, 'Proverbs 23:6', 'Proverbs', 23, 6, 'د شوم سړي ډوډۍ مه خوره او د خوندورو خوړو نه یې د یوې مړۍ تمه هم مه لره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_6.mp3', '', 1761754199, 1761754199),
(39929, 'Proverbs 23:7', 'Proverbs', 23, 7, 'ځکه هرڅه چې ته خورې هغه یې حسابوي او درته وایي چې راځه، ما سره وخوره او وڅښه! خو هغه د زړه له کومي دا خبره نه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_7.mp3', '', 1761754199, 1761754199),
(39930, 'Proverbs 23:8', 'Proverbs', 23, 8, 'کومه مړۍ چې دې خوړلې ده هغه به بېرته وګرځوې او ټولې خوږې خبرې به دې له منځه لاړې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_8.mp3', '', 1761754199, 1761754199),
(39931, 'Proverbs 23:9', 'Proverbs', 23, 9, 'کم‌عقل سړي ته هېڅکله نصیحت مه کوه ځکه هغه ستا د هوښیارۍ کلام ته په سپکه سترګه ګوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_9.mp3', '', 1761754199, 1761754199),
(39932, 'Proverbs 23:10', 'Proverbs', 23, 10, 'د ځمکې د حد پخوانۍ تیږه مه بېځایه کوه او د یتیمانو ځمکه په ظلم مه نیسه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_10.mp3', '', 1761754199, 1761754199),
(39933, 'Proverbs 23:11', 'Proverbs', 23, 11, 'ځکه چې د دوی ساتونکی زورور دی او هغه به د دوی حق ستا نه واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_11.mp3', '', 1761754199, 1761754199),
(39934, 'Proverbs 23:12', 'Proverbs', 23, 12, 'د زړه له کومي نصیحت قبول کړه او د علم او پوهې خبرو ته غوږ ونیسه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_12.mp3', '', 1761754199, 1761754199),
(39935, 'Proverbs 23:13', 'Proverbs', 23, 13, 'د خپل زوی په اصلاح کې لټي مه کوه. که ته یې په لښته ووهې نو مړ به نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_13.mp3', '', 1761754199, 1761754199),
(39936, 'Proverbs 23:14', 'Proverbs', 23, 14, 'نو هغه ته په لښته سزا ورکړه چې روح یې د قبر نه وژغورل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_14.mp3', '', 1761754199, 1761754199),
(39937, 'Proverbs 23:15', 'Proverbs', 23, 15, 'نو ای زما زویه! که ته د حکمت خاوند شې نو زړه به مې ډېر خوشحاله شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_15.mp3', '', 1761754199, 1761754199),
(39938, 'Proverbs 23:16', 'Proverbs', 23, 16, 'او کله چې ته رښتینې خبرې کوې نو زړه مې د خوشحالۍ نه ټوپونه وهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_16.mp3', '', 1761754199, 1761754199),
(39939, 'Proverbs 23:17', 'Proverbs', 23, 17, 'خپل زړه مه پرېږده چې له ګناهکارانو سره بخیلي وکړي بلکې هر وخت د څښتن نه په وېره کې اوسه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_17.mp3', '', 1761754199, 1761754199),
(39940, 'Proverbs 23:18', 'Proverbs', 23, 18, 'نو باور ولره چې په راتلونکې کې ستا دپاره پوره هیله ده او هېڅکله به ستا هیلې له منځه لاړې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_18.mp3', '', 1761754199, 1761754199),
(39941, 'Proverbs 23:19', 'Proverbs', 23, 19, 'نو ای زما زویه! ماته غوږ ونیسه او هوښیار اوسه او خپل زړه دې په سمه لار باندې ټینګ وساته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_19.mp3', '', 1761754199, 1761754199),
(39942, 'Proverbs 23:20', 'Proverbs', 23, 20, 'د شرابیانو سره ناسته ولاړه مه کوه او د خېټورو خلکو سره چې ډېره غوښه خوښوي مه ګرځه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_20.mp3', '', 1761754199, 1761754199),
(39943, 'Proverbs 23:21', 'Proverbs', 23, 21, 'ځکه چې شرابیان او خېټور خلک به خوار شي او ډېر خوب به هغوی ته زاړه کالي واغوندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_21.mp3', '', 1761754199, 1761754199),
(39944, 'Proverbs 23:22', 'Proverbs', 23, 22, 'د خپل پلار خبرو ته دې غوږ ونیسه چې تاته یې ژوند درکړی دی او د خپلې بوډۍ مور سپینو ویښتو ته په سپکه سترګه مه ګوره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_22.mp3', '', 1761754199, 1761754199),
(39945, 'Proverbs 23:23', 'Proverbs', 23, 23, 'حقیقت حاصل کړه او هغه په بیه واخله او د پیسو په خاطر حکمت، نصیحت او عقل مه خرڅوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_23.mp3', '', 1761754199, 1761754199),
(39946, 'Proverbs 23:24', 'Proverbs', 23, 24, 'د نېک سړي پلار ډېر خوشحاله وي او هوښیار زوی د خپل پلار دپاره د خوښۍ سبب وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_24.mp3', '', 1761754199, 1761754199),
(39947, 'Proverbs 23:25', 'Proverbs', 23, 25, 'پرېږده چې ستا مور او پلار په تا خوښ اوسي او مور دې چې ته یې زېږولی یې خوشحالي وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_25.mp3', '', 1761754199, 1761754199),
(39948, 'Proverbs 23:26', 'Proverbs', 23, 26, 'نو ای زما زویه! خپل زړه دې ماته راکړه او په ډېره خوشحالۍ زما په لارو قدم کېږده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_26.mp3', '', 1761754199, 1761754199),
(39949, 'Proverbs 23:27', 'Proverbs', 23, 27, 'ځکه زناکاره ښځه ستا دپاره ژوره کنده ده او هغه د یوې تنګې څاه په څېر ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_27.mp3', '', 1761754199, 1761754199),
(39950, 'Proverbs 23:28', 'Proverbs', 23, 28, 'هغه د یو داړه مار په شان په کمین کې ناسته وي او د خلکو ترمنځ خیانت زیاتوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_28.mp3', '', 1761754199, 1761754199),
(39951, 'Proverbs 23:29', 'Proverbs', 23, 29, 'څوک دی چې افسوس کوي او څوک دی چې غمجن دی؟ څوک دی چې شخړې جوړوي او څوک دی چې شکایت کوي؟ څوک دی چې ناحقه زخمونه لري او څوک دی چې سترګې یې سرې دي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_29.mp3', '', 1761754199, 1761754199),
(39952, 'Proverbs 23:30', 'Proverbs', 23, 30, 'دا هغه څوک دي چې تل شراب خوري او هر ډول شراب څښي او تل ورپسې ګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_30.mp3', '', 1761754199, 1761754199),
(39953, 'Proverbs 23:31', 'Proverbs', 23, 31, 'د شرابو سور رنګ ته په شوق مه ګوره چې په پیاله کې ځلیږي او په اسانۍ له ستوني نه تېریږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_31.mp3', '', 1761754199, 1761754199),
(39954, 'Proverbs 23:32', 'Proverbs', 23, 32, 'خو په اخر کې د مار په شان چیچل کوي او د منګري په څېر د زهرو ډک وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_32.mp3', '', 1761754199, 1761754199),
(39955, 'Proverbs 23:33', 'Proverbs', 23, 33, 'ستا سترګې به هر ډول حیرانوونکي شیان ویني او په زړه کې به دې ګډې وډې خبرې ګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_33.mp3', '', 1761754199, 1761754199),
(39956, 'Proverbs 23:34', 'Proverbs', 23, 34, 'د هغه چا په شان به شې چې د دریاب دپاسه خوب کوي او د څپو په سر پروت ټالۍ وهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_34.mp3', '', 1761754199, 1761754199),
(39957, 'Proverbs 23:35', 'Proverbs', 23, 35, 'ته به ووایې: «هغوی زه ووهلم خو زه دردمند نه شوم. زه یې وټکولم خو پوه پرې نه شوم. کله به راویښ شم چې د شرابو یوه بله پیاله وڅښم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs23_verse_35.mp3', '', 1761754199, 1761754199),
(39958, 'Genesis 7:1', 'Genesis', 7, 1, 'څښتن نوح ته وویل: «د خپلې ټولې کورنۍ سره کشتۍ ته ننوځه، ځکه چې په ټوله دنیا کې مې یوازېنی سړی ته ولیدلې چې نېک کارونه کوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis7_verse_1.mp3', '', 1761754199, 1761754199),
(39959, 'Genesis 7:2', 'Genesis', 7, 2, 'د ټولو پاکو حیواناتو څخه اووه، اووه جوړې نر او ښځه او د ناپاکو حیواناتو څخه یوه یوه جوړه نر او ښځه د ځان سره واخله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis7_verse_2.mp3', '', 1761754199, 1761754199),
(39960, 'Genesis 7:3', 'Genesis', 7, 3, 'او همدارنګه د هر ډول مرغانو څخه اووه جوړې نر او ښځه واخله، ترڅو د هغوی نسل د ځمکې په مخ باندې ژوندی پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis7_verse_3.mp3', '', 1761754199, 1761754199),
