(39962, 'Genesis 7:5', 'Genesis', 7, 5, 'نوح هغه ټول کارونه سرته ورسول چې څښتن ورته حکم کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis7_verse_5.mp3', '', 1761754199, 1761754199),
(39963, 'Genesis 7:6', 'Genesis', 7, 6, 'نوح د شپږ سوه کالو په عمر ؤ چې په ځمکه باندې سېلاب راغی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis7_verse_6.mp3', '', 1761754199, 1761754199),
(39964, 'Genesis 7:7', 'Genesis', 7, 7, 'نوح او د هغه زامن او ښځه او د زامنو ښځې یې د سېلاب څخه د ژغورلو په خاطر کشتۍ ته ننوتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis7_verse_7.mp3', '', 1761754199, 1761754199),
