(39973, 'Genesis 7:18', 'Genesis', 7, 18, 'اوبه ډېرې پورته شوې او کشتۍ د اوبو په مخ باندې روانه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis7_verse_18.mp3', '', 1761754199, 1761754199),
