(39980, 'Genesis 42:1', 'Genesis', 42, 1, 'کله چې یعقوب خبر شو چې په مصر کې غلې دانې شته، نو هغه خپلو زامنو ته وویل: «تاسو ولې هسې ناست یئ او یو بل ته ګورئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_1.mp3', '', 1761754199, 1761754199),
(39981, 'Genesis 42:2', 'Genesis', 42, 2, 'ما اورېدلي دي چې په مصر کې غلې دانې شته. هلته لاړ شئ او زمونږ دپاره یو څه واخلئ چې له لوږې څخه مړه نه شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_2.mp3', '', 1761754199, 1761754199),
(39982, 'Genesis 42:3', 'Genesis', 42, 3, 'نو د یوسف لس ورونه د غلو دانو د اخیستلو دپاره مصر ته لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_3.mp3', '', 1761754199, 1761754199),
(39983, 'Genesis 42:4', 'Genesis', 42, 4, 'خو یعقوب د یوسف ورور بنیامین د هغوی سره ونه لېږه، ځکه چې هغه وېرېده چې کوم زیان ورته ونه رسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_4.mp3', '', 1761754199, 1761754199),
(39984, 'Genesis 42:5', 'Genesis', 42, 5, 'نو د یعقوب زامن هم د هغو کنعانیانو په ډله کې وو چې د غلې د اخیستلو دپاره راغلي وو، ځکه چې په کنعان کې هم قحطي وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_5.mp3', '', 1761754199, 1761754199),
(39985, 'Genesis 42:6', 'Genesis', 42, 6, 'یوسف د مصر د دوهم مشر په توګه د ټولې دنیا په خلکو باندې غله خرڅوله، نو کله چې د یوسف ورونه راورسېدل، هغه ته یې د درناوي په خاطر خپل سرونه ټیټ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_6.mp3', '', 1761754199, 1761754199),
(39986, 'Genesis 42:7', 'Genesis', 42, 7, 'څنګه چې یوسف خپل ورونه ولیدل هغوی یې وپېژندل، خو ځان یې هغوی ته لکه د یو پردي په شان وښود او د هغوی سره یې په سخته لهجه خبرې وکړې. هغه پوښتنه ورڅخه وکړه: «له کوم ځای څخه راغلي یئ؟» هغوی ځواب ورکړ: «مونږ د کنعان څخه راغلي یو چې یو څه غله واخلو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_7.mp3', '', 1761754199, 1761754199),
(39987, 'Genesis 42:8', 'Genesis', 42, 8, 'که څه هم یوسف خپل ورونه وپېژندل، خو هغوی یوسف ونه پېژانده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_8.mp3', '', 1761754199, 1761754199),
(39988, 'Genesis 42:9', 'Genesis', 42, 9, 'په دې وخت کې یوسف خپل هغه خوبونه رایاد کړل چې د هغوی په اړه یې لیدلي وو او هغوی ته یې وویل: «تاسو جاسوسان یئ! تاسو د دې دپاره راغلي یئ چې وګورئ زمونږ په هېواد کې د کوم ځای امنیت کمزوری دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_9.mp3', '', 1761754199, 1761754199),
(39989, 'Genesis 42:10', 'Genesis', 42, 10, 'هغوی ځواب ورکړ: «نه زما باداره، ستا غلامان د غلې د اخیستلو دپاره راغلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_10.mp3', '', 1761754199, 1761754199),
(39990, 'Genesis 42:11', 'Genesis', 42, 11, 'مونږ ټول ورونه یو. مونږ جاسوسان نه یو، مونږ صادق خلک یو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_11.mp3', '', 1761754199, 1761754199),
(39991, 'Genesis 42:12', 'Genesis', 42, 12, 'یوسف هغوی ته وویل: «نه! تاسو د دې دپاره راغلي یئ چې وګورئ زمونږ په هېواد کې د کوم ځای امنیت کمزوری دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_12.mp3', '', 1761754199, 1761754199),
(39992, 'Genesis 42:13', 'Genesis', 42, 13, 'هغوی ځواب ورکړ: «ستا غلامان دولس ورونه د یو سړي زامن یو چې هغه د کنعان په خاوره کې اوسیږي. یو ورور مو مړ شوی دی او کشر ورور اوس زمونږ د پلار سره دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_13.mp3', '', 1761754199, 1761754199),
(39993, 'Genesis 42:14', 'Genesis', 42, 14, 'یوسف هغوی ته وویل: «دا همدا خبره ده لکه څنګه چې ما درته ویلي وو. تاسو جاسوسان یئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_14.mp3', '', 1761754199, 1761754199),
(39994, 'Genesis 42:15', 'Genesis', 42, 15, 'اوس به تاسو په دې ډول وازمایلی شئ. زه د فرعون په ژوندون باندې قسم خورم چې تاسو به هېڅکله له دې ځای نه لاړ نه شئ، تر هغې پورې چې ستاسو کشر ورور دلته رانه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_15.mp3', '', 1761754199, 1761754199),
(39995, 'Genesis 42:16', 'Genesis', 42, 16, 'ستاسو څخه دې یو تن لاړ شي چې ستاسو ورور راولي او پاتې به په زندان کې وساتل شي، ترڅو ستاسو خبره وازمایلی شي چې تاسو رښتیا وایئ او که نه. که داسې نه وي، نو د فرعون په نامه باندې قسم خورم چې تاسو جاسوسان یئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_16.mp3', '', 1761754199, 1761754199),
(39996, 'Genesis 42:17', 'Genesis', 42, 17, 'بیا یې هغوی درې ورځې په زندان کې وساتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_17.mp3', '', 1761754199, 1761754199),
(39997, 'Genesis 42:18', 'Genesis', 42, 18, 'په درېمه ورځ یوسف هغوی ته وویل: «زه له خدایه وېرېږم. زه به تاسو په یو شرط ژوندي پرېږدم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_18.mp3', '', 1761754199, 1761754199),
(39998, 'Genesis 42:19', 'Genesis', 42, 19, 'که چېرې تاسو صادقان یئ، نو ستاسو د ورونو څخه دې یو کس په زندان کې پاتې شي او نور کولای شي چې لاړ شي او خپلو وږیو کورنیو ته غله یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_19.mp3', '', 1761754199, 1761754199),
(39999, 'Genesis 42:20', 'Genesis', 42, 20, 'خو تاسو خامخا خپل کشر ورور ماته راولئ، نو ستاسو خبره به ثابته شي چې رښتیا وایئ او تاسو به مړه نه شئ.» هغوی رضا شول', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_20.mp3', '', 1761754199, 1761754199),
(40000, 'Genesis 42:21', 'Genesis', 42, 21, 'او یو بل ته یې وویل: «اوس مونږ دغه تکلیف د هغه کار په نتیجه کې وینو چې د خپل ورور سره مو کړی دی. مونږ ولیدل چې هغه په لوی مصیبت کې ؤ او مونږ ته یې د خپل ژوند دپاره زاري کوله، خو مونږ قبوله نه کړه. په همدې سبب دغه مصیبت په مونږ باندې راغلی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_21.mp3', '', 1761754199, 1761754199),
(40001, 'Genesis 42:22', 'Genesis', 42, 22, 'روبین ځواب ورکړ: «ایا تاسو ته مې ونه ویل چې د دې هلک په وړاندې ګناه مه کوئ؟ خو تاسو زما خبره ونه منله! اوس به مونږ د هغه د وینې حساب ورکوو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_22.mp3', '', 1761754199, 1761754199),
(40002, 'Genesis 42:23', 'Genesis', 42, 23, 'هغوی ته معلومه نه وه چې یوسف د هغوی په خبرو باندې پوهیږي، ځکه چې دوی د هغه سره د ترجمان په وسیله خبرې کولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_23.mp3', '', 1761754199, 1761754199),
(40003, 'Genesis 42:24', 'Genesis', 42, 24, 'یوسف د هغوی څخه لېرې لاړ او په ژړا شو. خو بېرته دوی ته راستون شو او بیا یې د هغوی سره خبرې وکړې. د هغوی څخه یې شمعون ونیوه او د هغوی په مخکې یې وتاړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_24.mp3', '', 1761754199, 1761754199),
(40004, 'Genesis 42:25', 'Genesis', 42, 25, 'یوسف امر وکړ چې د هغوی بوجۍ دې د غلو دانو څخه ډکې شي او د هر کس پیسې دې بېرته د هغه په بوجۍ کې کېښودلې شي او هغوی ته دې د سفر دپاره خواړه ورکړای شي. نو همداسې یې ورسره وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_25.mp3', '', 1761754199, 1761754199),
(40005, 'Genesis 42:26', 'Genesis', 42, 26, 'هغوی غله په خپلو خرو باندې بار کړه او روان شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_26.mp3', '', 1761754199, 1761754199),
(40006, 'Genesis 42:27', 'Genesis', 42, 27, 'په هغه ځای کې چې هغوی د شپې تېرولو دپاره پاتې شول، یو تن خپله بوجۍ خلاصه کړه چې خپل خره ته خوراک ورکړي، نو خپلې پیسې یې ولیدلې چې د بوجۍ په خوله کې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_27.mp3', '', 1761754199, 1761754199),
(40007, 'Genesis 42:28', 'Genesis', 42, 28, 'هغه خپلو ورونو ته وویل: «زما پیسې یې بېرته ماته راکړې دي او دلته زما په بوجۍ کې دي.» د هغوی زړونه ولوېدل او په رپېدلو یې یو بل ته مخ واړاوه او ویې ویل: «دا څه دي چې خدای زمونږ سره وکړل؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_28.mp3', '', 1761754199, 1761754199),
(40008, 'Genesis 42:29', 'Genesis', 42, 29, 'کله چې هغوی خپل پلار یعقوب ته د کنعان خاورې ته راغلل، نو هغه څه چې په هغوی باندې تېر شوي وو، هغه ته یې بیان کړل او ویې ویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_29.mp3', '', 1761754199, 1761754199),
(40009, 'Genesis 42:30', 'Genesis', 42, 30, '«د مصر دوهم مشر زمونږ سره په سخته لهجه خبرې وکړې او په مونږ باندې یې دا تور ولګاوه چې مونږ د هغه په خاوره کې جاسوسي کوو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_30.mp3', '', 1761754199, 1761754199),
(40010, 'Genesis 42:31', 'Genesis', 42, 31, 'خو مونږ هغه ته وویل چې مونږ صادق خلک یو، مونږ جاسوسان نه یو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_31.mp3', '', 1761754199, 1761754199);